func (this *GC) DrawRectangle(x int32, y int32, width int32, height int32) {
	if this.Handle == (nil) {
		Error(ERROR_GRAPHIC_DISPOSED)
	}
	var pool *cocoa.NSAutoreleasePool = this.CheckGC(GCDRAW)
	{
		defer func() {
			this.UncheckGC(pool)
		}()
		if width < 0 {
			x = x + width
			width = -width
		}
		if height < 0 {
			y = y + height
			height = -height
		}
		var rect cocoa.NSRect = cocoa.NSRect{}
		rect.X = float64(x) + this.data.DrawXOffset
		rect.Y = float64(y) + this.data.DrawYOffset
		rect.Width = float64(width)
		rect.Height = float64(height)
		var path *cocoa.NSBezierPath = this.data.Path
		path.AppendBezierPathWithRect(rect)
		var pattern *Pattern = this.data.ForegroundPattern
		if pattern != (nil) {
			this.SetPatternPhase(pattern)
		}
		if pattern != (nil) && pattern.gradient != (nil) {
			this.StrokePattern(path, pattern)
		} else {
			path.Stroke()
		}
		path.RemoveAllPoints()
	}
}

func (this *GC) DrawRectangleRect(rectLike RectangleLike) {
	var rect *Rectangle
	if rectLike != nil {
		rect = rectLike.AsRectangle()
	}
	_ = rect
	if this.Handle == (nil) {
		Error(ERROR_GRAPHIC_DISPOSED)
	}
	if rect == (nil) {
		Error(ERROR_NULL_ARGUMENT)
	}
	this.DrawRectangle(rect.X, rect.Y, rect.Width, rect.Height)
}

func (this *GC) DrawRoundRectangle(x int32, y int32, width int32, height int32, arcWidth int32, arcHeight int32) {
	if this.Handle == (nil) {
		Error(ERROR_GRAPHIC_DISPOSED)
	}
	if arcWidth == 0 || arcHeight == 0 {
		this.DrawRectangle(x, y, width, height)
		return
	}
	var pool *cocoa.NSAutoreleasePool = this.CheckGC(GCDRAW)
	{
		defer func() {
			this.UncheckGC(pool)
		}()
		var path *cocoa.NSBezierPath = this.data.Path
		var rect cocoa.NSRect = cocoa.NSRect{}
		rect.X = float64(x) + this.data.DrawXOffset
		rect.Y = float64(y) + this.data.DrawYOffset
		rect.Width = float64(width)
		rect.Height = float64(height)
		path.AppendBezierPathWithRoundedRect(rect, float64(float32(arcWidth)/2.0), float64(float32(arcHeight)/2.0))
		var pattern *Pattern = this.data.ForegroundPattern
		if pattern != (nil) {
			this.SetPatternPhase(pattern)
		}
		if pattern != (nil) && pattern.gradient != (nil) {
			this.StrokePattern(path, pattern)
		} else {
			path.Stroke()
		}
		path.RemoveAllPoints()
	}
}
